"""Beginner-friendly DSA practice problems (original wording). Function-style, like LeetCode.
tests: [(args_list, expected)]. The first two tests are shown as examples; the rest stay hidden."""
import itertools

LL = lambda xs: {"$list": xs}  # noqa: E731  linked-list marker used by the test runner


def PB(slug, title, cat, diff, fn, desc, constraints, starter, solution, tests, hint="", ll=False):
    return {"slug": slug, "title": title, "category": cat, "difficulty": diff, "function_name": fn,
            "description": desc, "constraints": constraints, "starter_code": starter, "solution": solution,
            "hint": hint, "tests": [{"args": a, "expected": e, **({"ll_result": True} if ll else {})} for a, e in tests]}


def stub(sig, note="write your code here"):
    return f"def {sig}:\n    # {note}\n    pass\n"


NODE_NOTE = "ListNode is provided: node.val is the value, node.next is the next node (or None)."

